CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_reserving.loss_development
COMMENT 'The loss-development triangle as a governed view: for every accident year and development lag, the incremental and cumulative paid and incurred, derived by summation over claim transactions. Nothing is stored - the triangle is a semantic layer over claim.claim_transaction, so it always reconciles to the penny with the ledger and the claims sub-system. Accident year is the year of loss; development lag is transaction year minus accident year. Amounts are in original currency - group by or filter on currency_code before summing. Grain: One row per accident year per development lag per line of business per currency.'
AS
WITH movements AS (
  SELECT
    YEAR(c.loss_date)                                   AS accident_year,
    YEAR(ct.transaction_date) - YEAR(c.loss_date)       AS development_lag,
    p.line_of_business_code                             AS line_of_business_code,
    ct.currency_code                                    AS currency_code,
    ct.claim_transaction_type_code                      AS ttype,
    ct.amount                                           AS amount
  FROM lr_serverless_aws_us_catalog.bricksurance_claim.claim_transaction ct
  JOIN lr_serverless_aws_us_catalog.bricksurance_claim.claim  c ON c.claim_id  = ct.claim_id
  JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = c.policy_id
  WHERE YEAR(ct.transaction_date) >= YEAR(c.loss_date)
),
incremental AS (
  SELECT
    accident_year, development_lag, line_of_business_code, currency_code,
    SUM(CASE WHEN ttype IN ('INDEMNITY_PAYMENT','EXPENSE_PAYMENT') THEN amount
             WHEN ttype = 'RECOVERY' THEN amount ELSE 0 END)          AS incremental_paid,
    SUM(CASE WHEN ttype IN ('INDEMNITY_PAYMENT','EXPENSE_PAYMENT','RECOVERY','CASE_RESERVE_MOVEMENT')
             THEN amount ELSE 0 END)                                  AS incremental_incurred
  FROM movements
  GROUP BY accident_year, development_lag, line_of_business_code, currency_code
)
SELECT
  accident_year,
  development_lag,
  line_of_business_code,
  currency_code,
  incremental_paid,
  incremental_incurred,
  SUM(incremental_paid) OVER (
    PARTITION BY accident_year, line_of_business_code, currency_code
    ORDER BY development_lag ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
  ) AS cumulative_paid,
  SUM(incremental_incurred) OVER (
    PARTITION BY accident_year, line_of_business_code, currency_code
    ORDER BY development_lag ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
  ) AS cumulative_incurred
FROM incremental;
